let state=null,meta=null,draft=null,previewStop=null,selected=null,playing=false,timer=null,generation=0,busy=false,drawer='positions',tab='trade',noticeTimer,tool='cursor',editVersion=0,draftSaveWanted=false;
let stepActive=false, mutationWaiters=[];
const tradeBusy=()=>busy&&!stepActive;
