function notify(message){clearTimeout(noticeTimer);$('notice').textContent=message;noticeTimer=setTimeout(()=>{$('notice').textContent=''},9000)}
async function api(path,data){let r;try{r=await fetch('/api/'+path,{...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{}),signal:AbortSignal.timeout(15000)});}catch(e){throw Error('Connection unavailable. Restart the local server and reload this page to reconcile the account before retrying. An interrupted request may already have completed.')}let x=await r.json();if(!r.ok){if(x.state)accept(x.state);throw Error(x.error)}return x}
function accept(x,paint=true){if(settingsSession!==x.session.id){settingsSession=x.session.id;orderBlocksSettings=!!x.session.ui?.orderBlocks;indicatorSettings={NQ:normalizeConfig(x.session.ui?.indicators?.NQ||defaultConfig()),ES:normalizeConfig(x.session.ui?.indicators?.ES||defaultConfig())};document.body.classList.toggle('side-collapsed',x.session.ui?.sideCollapsed!==false);$('drawerContent').style.height=(x.session.ui?.drawerHeight||180)+'px'}const justEnded=x.session.ended&&state?.session.id===x.session.id&&!state.session.ended;state=x;draft=x.session.draft?{...x.session.draft}:null;localStorage.setItem('lucidPracticeSession',x.session.id);if(x.session.ended)pause();if(paint)render();if(justEnded)queueMicrotask(()=>$('navJournal').click())}
// A single in-flight mutation; buttons are disabled before awaiting. Server adds revision/idempotency guards.
async function command(action,data={}){const sessionId=state?.session.id;while(busy){if(action==='step')return false;await new Promise(resolve=>mutationWaiters.push(resolve));if(state?.session.id!==sessionId)return false;}busy=true;stepActive=action==='step';setBusy();try{const before=state?.session.activity?.length||0,version=editVersion;let x=await api(action,mutationPayload(state,+$('tf').value,data,crypto.randomUUID()));const newerDraft=(action==='step'||['draft','ui','note'].includes(action)&&editVersion!==version)?draft:null;accept(x,false);if(action==='step')$('quickStatus').textContent='';if(newerDraft){if(action==='step'&&x.session.draft&&['instrument','side','qty','stop','target'].every(k=>newerDraft[k]===x.session.draft[k]))newerDraft.ml_prediction=x.session.draft.ml_prediction;draft=newerDraft;if(action==='draft')draftSaveWanted=true}let event=x.session.activity?.slice(before).at(-1);if(event&&['Open','Closed','Rejected','Cancelled'].includes(event.kind))notify(`${event.kind}: ${event.reason}`);return true}catch(e){notify(e.message);$('sessionError').textContent=e.message;if(action==='step')pause();return false}finally{busy=false;stepActive=false;render();const waiting=mutationWaiters.splice(0);waiting.forEach(resolve=>resolve());if(draftSaveWanted&&draft){draftSaveWanted=false;queueMicrotask(persistDraft)}}}
function setBusy(){if(stepActive)return;for(let id of ['long','short','tf','contract','submit','cancelOrder','applyStop','closePosition','step','create','resume'])$(id).disabled=tradeBusy();}
function pause(){playing=false;generation++;clearTimeout(timer);$('play').innerHTML='▶ <span>Play</span>'}
async function loop(g){if(!playing||g!==generation)return;let started=performance.now();if(!busy)await command('step');if(playing&&g===generation&&!state?.session.ended)timer=setTimeout(()=>loop(g),Math.max(16,+$('speed').value-(performance.now()-started)))}
function play(){if(playing){pause();return}if(!state||state.session.ended||busy)return;charts.forEach(c=>c.current());playing=true;const g=++generation;$('play').innerHTML='Ⅱ <span>Pause</span>';loop(g)}
function setTab(t){tab=t;$('tradePanel').hidden=t!=='trade';$('reviewPanel').hidden=t!=='review';for(let k of ['trade','review']){$(k+'Tab').classList.toggle('selected',t===k);$(k+'Tab').setAttribute('aria-selected',String(t===k))}if(t==='review')review()}
function recentChoice(){return meta?.broad_data?.[$('dataset').value]||meta?.exchange_data?.[$('dataset').value]||meta?.recent_data?.[$('dataset').value]}
let dateIndex=null,dateGeneration=0,dateSelection=null;
async function chooseLatest(){if(!dateIndex?.latest){$('sessionError').textContent='No complete local session yet. See the README import instructions.';return}$('dataset').value='auto';$('startDate').value=(Object.keys(dateIndex.days).sort().reverse().find(d=>dateIndex.days[d].some(r=>r.full&&r.minutes===+$('executionResolution').value))||dateIndex.latest)+'T08:30';dateSelection=null;await previewDate()}
