 meta=await api('meta');$('sessionWarnings').textContent=(meta.session_warnings||[]).join(' ');$('sessionWarnings').hidden=!meta.session_warnings?.length;$('savedSessions').replaceChildren(new Option('Choose a saved session…',''));
 for(let s of meta.sessions)$('savedSessions').add(new Option(`${time(s.clock)} Chicago · ${money(s.balance)}`,s.id));
