$('latestSession').onclick=chooseLatest;

async function sessionDialog(){pause();try{await loadMeta();dateIndex=await api('dates');$('dateCoverage').textContent=dateIndex.latest?`Local history: ${dateIndex.first} through ${dateIndex.latest}.`:'No local data imported. Follow the CSV import steps in README.md, then reopen Sessions.';$('randomStart').value||=Object.keys(dateIndex.days).sort().find(d=>dateIndex.days[d].some(r=>r.full&&r.practice_eligible!==false))||dateIndex.first;$('randomEnd').value||=dateIndex.latest;$('sessionError').textContent='';await chooseLatest();updateStartMode();$('sessionDialog').showModal()}catch(e){notify('Could not load sessions: '+e.message)}}
async function restore(id){if(busy)return;pause();busy=true;setBusy();try{const requestedTf=+$('tf').value;let x=await api('state?id='+id+'&tf='+requestedTf);let ui=x.session.ui||{};if(ui.contract)$('contract').value=ui.contract;if(ui.tf)$('tf').value=ui.tf;$('split').setAttribute('aria-pressed',String(!!ui.split));if(ui.tf&&+ui.tf!==requestedTf)x=await api('state?id='+id+'&tf='+ui.tf);selected=null;previewStop=null;accept(x);charts.forEach(c=>c.fit());$('sessionDialog').close()}catch(e){notify(e.message)}finally{busy=false;render()}}
function saveUI(){if(!state)return;return command('ui',{ui:{...state.session.ui,orderBlocks:orderBlocksSettings,indicators:indicatorSettings,sideCollapsed:document.body.classList.contains('side-collapsed'),drawerHeight:parseInt($('drawerContent').style.height)||180,contract:$('contract').value,tf:+$('tf').value,split:$('split').getAttribute('aria-pressed')==='true'}})}
async function startDraft(side,qty=null){if(!state){sessionDialog();return}if(tradeBusy()||state.session.pending||state.session.position||state.session.ended)return;previewStop=null;selected=null;let d=practiceDraft(state,$('contract').value,side,qty??1);if(!d){notify('No completed execution price is available here.');return}if(qty!==null)d.qty=qty;if(await command('draft',{draft:d})){setTab('trade');charts.forEach(c=>c.fit())}}
function readDraft(){if(!draft)return;editVersion++;draft.qty=+$('quantity').value;draft.stop=+$('stopPrice').value;draft.target=+$('targetPrice').value;$('submit').textContent=`Submit ${draft.side===1?'Buy':'Sell'} · ${draft.qty} ${draft.instrument}`;updateMetrics();renderCharts()}
async function persistDraft(){if(!draft)return;if(busy){draftSaveWanted=true;return;}let d={...draft};if(![d.stop,d.target].every(Number.isFinite))return;await command('draft',{draft:d})}
function dragLevel(key,value,done){if(tradeBusy())return;if(draft){if(value!==null){editVersion++;draft[key]=value;$(key==='stop'?'stopPrice':'targetPrice').value=value;updateMetrics();renderCharts()}if(done)persistDraft()}else if(state?.session.position&&key==='stop'){if(value!==null){previewStop=value;$('tightStop').value=value;renderCharts();validateTight()}if(done)notify('Stop preview only. Choose Apply tighter stop to submit.')}}
function validateTight(){let p=state?.session.position,k=p?state.known_prices[p.source]:null,v=previewStop,valid=p&&k?.fresh&&Number.isFinite(v)&&v>0&&(p.side===1?(p.stop==null||v>=p.stop)&&v<k.price:(p.stop==null||v<=p.stop)&&v>k.price)&&v!==p.stop; $('applyStop').disabled=tradeBusy()||!valid; $('tightValidation').textContent=v===null||v===p?.stop?'':valid?'Ready to apply tighter stop.':!k?.fresh?'Wait for a fresh price before changing the stop.':'Stop must tighten the current risk and remain beyond the current price.';return valid}
function metrics(o,isDraft){if(o.stop==null||o.target==null)return {entry:o.entry??state.known_prices[source(o.instrument)]?.price,risk:null,reward:null,ratio:NaN,distance:NaN};let s=state.session,k=state.known_prices[source(o.instrument)],entry=isDraft?k?.price:o.entry||o.signal_close||k?.price,p=POINT[o.instrument],fees=2*s.fee*o.qty;let risk=isDraft?estimate(o,state).risk:o.planned_risk??o.requested_risk;let reward=(o.target-entry)*o.side*p*o.qty-fees;if(state.session.position&&o.original_qty!==undefined){let paid=o.fees_paid??s.fee*o.qty;let gross=o.realized_gross||0;risk=Math.max(0,-(gross+(o.stop-entry)*o.side*p*o.qty-paid-s.fee*o.qty-s.slip*.25*p*o.qty));reward=gross+(o.target-entry)*o.side*p*o.qty-paid-s.fee*o.qty;}return {entry,risk,reward,ratio:reward/risk,distance:Math.abs(entry-o.stop)}}
