function selectTrade(id){pause();selected=id;previewStop=null;let t=state.session.trades.find(t=>t.id===id)||state.session.position;if(t){document.body.classList.remove('side-collapsed');$('contract').value=t.instrument;setTab('review');render();charts.forEach(c=>c.fit());queueUI()}}
function flowHTML(f){if(!f?.available)return `<div class="review-section"><h3>Order-flow evidence</h3><p>Unavailable: ${esc(f?.reason||'Not captured in this saved review. New entries capture supported TBBO evidence.')}</p></div>`;let q=f.last_pretrade_quote;return `<div class="review-section"><h3>Order-flow evidence · ${esc(f.contract)}</h3><p>Completed five-minute window ending ${time(f.end_ns/1e9)} Chicago. Only records received by the decision clock.</p><ul><li>Trade records: ${f.trades.toLocaleString()}</li><li>Buy aggressor volume: ${f.buy_volume.toLocaleString()}</li><li>Sell aggressor volume: ${f.sell_volume.toLocaleString()}</li><li>Unknown side volume: ${f.unknown_volume.toLocaleString()}</li><li>Delta (buy − sell): ${f.delta.toLocaleString()} contracts</li><li>Mean pre-trade spread: ${f.mean_pretrade_spread_points===null?'Unavailable':price(f.mean_pretrade_spread_points)+' pts'}</li><li>Usable BBO snapshots: ${f.valid_quote_records.toLocaleString()} / ${f.trades.toLocaleString()}</li></ul>${q?`<p>Last pre-trade snapshot: bid ${price(q.bid)} × ${q.bid_size}, ask ${price(q.ask)} × ${q.ask_size}. This is not a live quote.</p>`:''}<details><summary>Volume at price · observed trades</summary><table><thead><tr><th>Price</th><th>Buy</th><th>Sell</th><th>Unknown</th></tr></thead><tbody>${Object.entries(f.footprint).sort((a,b)=>+b[0]-+a[0]).map(([p,v])=>`<tr><td>${price(+p)}</td><td>${v.buy}</td><td>${v.sell}</td><td>${v.unknown}</td></tr>`).join('')}</tbody></table></details><p>${esc(f.mapping_method||'Explicit contract mapping')}. ${esc(f.note)}</p><p>ES/NQ source-contract evidence; not MES/MNQ order flow. These statistics are descriptive; the ML estimate is shown separately.</p></div>`}
function review(){if(!state)return;let t=state.session.trades.find(t=>t.id===selected)||state.session.position||state.session.pending||state.session.trades.at(-1);if(draft){$('reviewContent').innerHTML='<h2>Draft review</h2>'+draftML(draft);return}if(!t){$('reviewContent').innerHTML='<h2>Trade review</h2><p class="quiet">Select a completed trade in the Trades drawer or an entry/exit marker to review its execution and risk.</p>';return}let e=t.entry_review||{},closed=t.net!==undefined;let sections=`<h2>${t.side===1?'Long':'Short'} ${t.qty} ${esc(t.instrument)}</h2><p class="quiet">${time(t.entry_at??t.decision)} Chicago</p><div class="review-result ${closed?(t.net>=0?'positive':'negative'):''}">${closed?money(t.net):t.entry===undefined?'Pending entry':'Open position'}</div><div class="review-section"><h3>1 · Entry context</h3><p>Captured at ${time(t.decision)}, before entry. Descriptive evidence, not a buy/sell score.</p><p>Manual practice entry. Review your thesis, timing and position size against the chart. No automated entry score is provided.</p></div><div class="review-section"><h3>2 · Risk</h3><p>Initial planned risk ${money(t.planned_risk??t.requested_risk)} including modeled costs. Initial price target/stop ratio ${((t.planned_RR??e.risk_at_decision?.planned_RR_before_fill)==null?'—':Number(t.planned_RR??e.risk_at_decision?.planned_RR_before_fill).toFixed(2))}R.</p><p>${t.risk_overrun?'⚠ Realized loss exceeded planned risk. Gap/slippage assumptions can cause overruns.':t.entry===undefined?'Submission passed preliminary risk checks; the actual next-open fill will be checked again.':'Entry was accepted under the settings at submission. Acceptance does not establish bounded risk. Stops are not guaranteed loss caps.'}</p></div><div class="review-section"><h3>3 · Management</h3>${(t.management||[]).length?'<ul>'+t.management.map(m=>`<li>${time(m.at)}: ${esc(m.action)}${m.new!==undefined?' to '+price(m.new):''}${m.delta!==undefined?' · '+(m.delta>0?'+':'')+m.delta+' contracts':''}${m.price!==undefined?' @ '+price(m.price):''}</li>`).join('')+'</ul>':'<p>No manual management changes.</p>'}</div><div class="review-section"><h3>4 · Outcome & fill sequence</h3><p>${t.entry===undefined?'Awaiting next-open entry.':`<b>E1</b> Original entry at ${price(t.original_entry??t.entry)}.`} ${closed?`<b>X2</b> Exit at ${price(t.exit)}; outcome available ${time(t.exit_available)}.`:'No completed exit yet.'}</p>${closed?`<p>${esc(t.reason)}. Fees ${money(t.fees)}. Realized ${(t.realized_R==null?'—':Number(t.realized_R).toFixed(2))}R.</p>`:''}${closed&&t.exit_available===t.entry_at+(state.session.base_seconds||300)?'<p><b>Entry and exit occurred in the same source bar.</b> E1 and X2 are separate markers. Tick sequence is unknown; if both stop and target were touched, stop is assumed first.</p>':''}<p>Profit or loss does not establish whether the entry had an edge.</p></div>`;$('reviewContent').innerHTML=sections}
async function addDrawing(d){if(!state||busy)return;await command('note',{drawings:state.session.drawings.concat(d)})}
$('long').onclick=()=>startDraft(1);$('short').onclick=()=>startDraft(-1);
for(let id of ['quantity','stopPrice','targetPrice']){$(id).oninput=readDraft;$(id).onchange=()=>{if(!draft)return;if(id!=='quantity')$(id).value=snap(+$(id).value);readDraft();persistDraft()}}
$('submit').onclick=async()=>{if(!draft||estimate(draft,state).error||tradeBusy())return;let d={...draft};if(await command('order',d)){charts.forEach(c=>c.fit());previewStop=null}};
$('cancelOrder').onclick=()=>{return command(draft?'draft':'cancel',draft?{draft:null}:{})};
$('tightStop').oninput=()=>{previewStop=snap(+$('tightStop').value);validateTight();renderCharts()};$('applyStop').onclick=async()=>{if(!validateTight())return;if(await command('manage',{stop:previewStop})){previewStop=null;render()}};
$('closePosition').onclick=()=>{command('manage',{flatten:true})};$('play').onclick=play;$('step').onclick=()=>{pause();if(state)command('step')};
$('sessionButton').onclick=$('startWelcome').onclick=sessionDialog;$('settingsButton').onclick=()=>{pause();let s=state?.session;if(!s)return;$('riskEnforced').checked=s.risk_enforced!==false;$('riskAmount').value=s.risk;$('lossAmount').value=s.initial-s.floor;$('riskContracts').value=s.max_micro??s.challenge?.config.max_micro??10;$('riskError').textContent='';$('riskDetails').textContent='Starting balance '+money(s.initial)+'. Fee '+money(s.fee)+' per contract/side. Slippage '+s.slip+' ticks. '+(s.challenge?'Challenge loss limits and contract cap remain enforced.':'Changes apply to this attempt and are recorded.');$('riskDialog').showModal()};$('helpButton').onclick=()=>$('helpDialog').showModal();
$('sessionForm').onsubmit=async e=>{e.preventDefault();pause();selected=null;previewStop=null;let data={random_start:$('randomStartMode').checked,random_from:$('randomStart').value,random_through:$('randomEnd').value,local_date:$('startDate').value,dataset:$('dataset').value,execution_resolution:$('executionResolution').value,date_selection:dateSelection};for(let id of ['balance','risk','loss','fee','slip'])data[id]=+$(id).value;if($('challengeEnabled').checked)data.challenge={...(propCatalog.find(p=>p.id===$('challengePreset').value)?.config||{}),reference:propCatalog.find(p=>p.id===$('challengePreset').value)||null,daily_action:$('challengeAction').value,min_days:+$('challengeDays').value,max_micro:+$('challengeCap').value,micro_per_mini:+$('challengeRatio').value,phase:$('challengePhase').value,target:+$('challengeTarget').value,drawdown:+$('challengeDrawdown').value,mode:$('challengeMode').value,lock_profit:+$('challengeLock').value,daily_loss:+$('challengeDaily').value,daily_basis:$('challengeBasis').value,consistency:+$('challengeConsistency').value,denominator:$('challengeDenominator').value};$('tf').value=$('executionResolution').value;if(await command('new',data)){clearTimeout(noticeTimer);$('notice').textContent='';$('sessionError').textContent='';await saveUI();$('sessionDialog').close();charts.forEach(c=>c.fit());setTab('trade');await loadMeta()}};
$('resume').onclick=()=>{if($('savedSessions').value)restore($('savedSessions').value)};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
$('contract').onchange=()=>{selected=null;previewStop=null;render();charts.forEach(c=>c.fit());queueUI()};$('tf').onchange=async()=>{pause();if(!state)return;clearTimeout(uiSaveTimer);const requested=$('tf').value;$('charts').classList.add('loading-chart');$('charts').setAttribute('aria-busy','true');$('charts').dataset.loading='Loading '+requested+' minute chart…';charts.forEach(c=>{c.cursor=null;c.tip.hidden=true});try{const ok=await saveUI();if(!ok)$('tf').value=String(state.chart_timeframe);render()}finally{$('charts').classList.remove('loading-chart');$('charts').setAttribute('aria-busy','false')}};$('split').onclick=()=>{let split=$('split').getAttribute('aria-pressed')!=='true';$('split').setAttribute('aria-pressed',String(split));renderCharts();queueUI()};
$('tradeTab').onclick=()=>setTab('trade');$('reviewTab').onclick=()=>setTab('review');$('fitTrade').onclick=()=>{if(!selected&&state?.session.trades.length)selected=state.session.trades.at(-1).id;renderCharts();charts.forEach(c=>c.fit())};$('goLive').onclick=()=>charts.forEach(c=>c.current());$('autoPrice').onclick=()=>charts.forEach(c=>c.autoPrice());$('zoomIn').onclick=()=>charts.forEach(c=>c.zoom(.8));$('zoomOut').onclick=()=>charts.forEach(c=>c.zoom(1.25));
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;document.querySelectorAll('[data-tool]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});charts.forEach(c=>c.setTool(tool))});$('clearDrawing').onclick=()=>{if(state)command('note',{drawings:[]})};
document.querySelectorAll('[data-drawer]').forEach(b=>b.onclick=()=>{drawer=drawer===b.dataset.drawer?null:b.dataset.drawer;renderDrawer()});$('drawerToggle').onclick=()=>{drawer=drawer?null:'history';renderDrawer()};
document.addEventListener('keydown',e=>{if(e.defaultPrevented)return;if(['INPUT','SELECT','TEXTAREA','BUTTON'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();play()}if(e.key==='ArrowRight'&&e.target.tagName!=='CANVAS'){e.preventDefault();pause();if(state)command('step')}if(e.key==='Escape'){charts.forEach(c=>c.setTool('cursor'));document.querySelector('[data-tool=cursor]').click()}});
loadMeta().then(async()=>{let id=localStorage.getItem('lucidPracticeSession');if(id&&meta.sessions.some(s=>s.id===id))await restore(id);else render()}).catch(e=>notify(e.message));

function queueUI(){clearTimeout(uiSaveTimer);uiSaveTimer=setTimeout(async()=>{if(busy){queueUI();return}await saveUI()},180)}
function indicatorPanel(){$('indicatorError').textContent='';$('orderBlocks').checked=orderBlocksSettings;let k=$('indicatorChart').value,query=$('indicatorSearch').value.toLowerCase();$('indicatorCatalog').innerHTML=Object.entries(catalog).filter(([t,n])=>(t+' '+n).toLowerCase().includes(query)).map(([t,n])=>`<button data-add-indicator="${t}"><b>${t}</b><span>${n}</span><span>＋</span></button>`).join('');$('indicatorList').innerHTML=indicatorSettings[k].map((x,i)=>`<div class="indicator-row" data-indicator-id="${esc(x.id)}"><div class="indicator-row-head"><strong>${x.type}${['SMA','EMA','BB','RSI','ATR'].includes(x.type)?' '+x.period:''}</strong><button data-visible="${i}" aria-label="${x.visible?'Hide':'Show'} ${x.type} ${i+1}">${x.visible?'Visible':'Hidden'}</button><button data-remove="${i}" aria-label="Remove ${x.type} ${i+1}">×</button></div><div class="indicator-fields">${['SMA','EMA','BB','RSI','ATR'].includes(x.type)?`<label>Period<input aria-label="${x.type} ${i+1} period" data-index="${i}" data-field="period" type="number" min="2" max="200" value="${x.period}"></label>`:''}${x.type==='BB'?`<label>Std deviations<input aria-label="BB ${i+1} deviations" data-index="${i}" data-field="mult" type="number" min="0.1" max="5" step=".1" value="${x.mult}"></label>`:''}${x.type==='MACD'?['fast','slow','signal'].map(f=>`<label>${f}<input aria-label="MACD ${f}" data-index="${i}" data-field="${f}" type="number" min="2" max="200" value="${x[f]}"></label>`).join(''):''}<label>Color<input aria-label="${x.type} ${i+1} color" data-index="${i}" data-field="color" type="color" value="${x.color}"></label></div></div>`).join('')||'<p class="quiet">No indicators. Add one above.</p>'}
$('indicatorsButton').onclick=()=>{pause();$('indicatorChart').value=source($('contract').value);indicatorPanel();$('indicatorDialog').showModal()};$('indicatorChart').onchange=indicatorPanel;$('indicatorSearch').oninput=indicatorPanel;
$('indicatorCatalog').onclick=e=>{let type=e.target.closest('[data-add-indicator]')?.dataset.addIndicator;if(!type)return;let k=$('indicatorChart').value;if(indicatorSettings[k].length>=16){$('indicatorError').textContent='Up to 16 indicators per chart.';return}indicatorSettings[k].push(defaults(type));indicatorPanel();renderCharts();queueUI()};
$('indicatorList').onclick=e=>{let remove=e.target.closest('[data-remove]'),toggle=e.target.closest('[data-visible]'),k=$('indicatorChart').value;if(remove)indicatorSettings[k].splice(+remove.dataset.remove,1);else if(toggle){let x=indicatorSettings[k][+toggle.dataset.visible];x.visible=!x.visible}else return;indicatorPanel();renderCharts();queueUI()};
$('indicatorList').oninput=e=>{let {index,field}=e.target.dataset;if(index===undefined||e.target.value==='')return;let k=$('indicatorChart').value;indicatorSettings[k][+index][field]=field==='color'?e.target.value:+e.target.value;indicatorSettings[k]=normalizeConfig(indicatorSettings[k]);renderCharts();queueUI()};
$('indicatorList').onchange=e=>{let {index,field}=e.target.dataset;if(index===undefined)return;let k=$('indicatorChart').value,x=indicatorSettings[k][+index];x[field]=field==='color'?e.target.value:+e.target.value;indicatorSettings[k]=normalizeConfig(indicatorSettings[k]);indicatorPanel();renderCharts();queueUI()};
$('panelToggle').onclick=()=>{document.body.classList.toggle('side-collapsed');$('panelToggle').setAttribute('aria-expanded',String(!document.body.classList.contains('side-collapsed')));queueUI()};
let resizeStart=null,resizeFrame=null;
$('drawerResize').onpointerdown=e=>{resizeStart={y:e.clientY,h:$('drawerContent').getBoundingClientRect().height};if(!drawer){drawer='positions';renderDrawer()}e.target.setPointerCapture(e.pointerId)};
$('drawerResize').onpointermove=e=>{if(!resizeStart)return;let height=Math.max(70,Math.min(innerHeight*.5,resizeStart.h+resizeStart.y-e.clientY));cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>{$('drawerContent').style.height=height+'px'})};
$('drawerResize').onpointerup=()=>{resizeStart=null;queueUI()};$('drawerResize').onkeydown=e=>{if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(!drawer){drawer='positions';renderDrawer()}$('drawerContent').style.height=Math.max(70,Math.min(innerHeight*.5,(parseInt($('drawerContent').style.height)||180)+(e.key==='ArrowUp'?20:-20)))+'px';queueUI()}};

