function holidaySchedule(a){if(!a?.calendar_version)return '';let clock=t=>t?new Date(t*1000).toLocaleTimeString('en-US',{timeZone:'America/Chicago',hour:'2-digit',minute:'2-digit'}):'unverified';return `<p><strong>${esc(a.date)} · ${esc(a.holiday||'Regular schedule')}</strong><br>${a.holiday?`Exchange matching ends ${clock(a.market_close)} · firm flatten ${clock(a.close)} Chicago<br>${esc(a.note)}`:`Calendar: ${esc(a.verification)}`}</p>`}
function holidayPreset(c){let cal=c.dated_calendar;if(!cal)return '';return `<p>Holiday audit: ${esc(cal.start)}–${esc(cal.end)} · Chicago time</p><ul>${Object.entries(cal.dates).map(([d,h])=>`<li>${esc(d)} ${esc(h.name)}: exchange stops ${esc(h.market_close)}; firm flatten ${esc(h.flatten||'unverified — entries blocked for this session')}.</li>`).join('')}</ul>`}
function renderChallenge(){let a=state?.session.challenge;$('challengeCard').hidden=!a;$('challengeOverview').hidden=!a;if(!a)return;let c=a.config,ref=c.reference, label=ref?`${ref.firm} ${ref.plan}`:'Custom challenge';$('challengeOverview').innerHTML=`<strong>${esc(label)}</strong><span>${state.session.ended?'Attempt ended · '+esc(a.status.replaceAll('_',' ')):c.phase==='funded'?'Funded risk practice · payouts not simulated':'To modeled pass: '+money(a.remaining_target)}</span><span>Consistency: ${c.consistency?`${a.consistency_pct==null?'No positive net profit yet':a.consistency_pct.toFixed(2)+'%'} / ${c.consistency}% · ${a.consistency_met?'met':'not met'}`:'not required in this phase'}</span>`;$('challengeSummary').textContent=`${label} · ${a.status.replaceAll('_',' ')} · ${money(a.profit)}`;let warnings=[...a.reasons,...a.uncertainties,...(a.limitations||[])];$('challengeProgress').innerHTML=`<p>${c.phase==='funded'?'Funded practice · no pass target':'Target remaining <strong>'+money(a.remaining_target)+'</strong>'}<br>Loss floor ${money(a.floor)}${a.next_floor!==undefined?` · next session ${money(a.next_floor)}`:''}<br>${a.trading_days||0} trading days · ${a.paused_day?'Entries paused until next session':'fees included'}${state.entry_block?`<br>${esc(state.entry_block)}`:''}</p><p class="consistency-progress"><b>Consistency ${c.consistency?c.consistency+'%':'not required'}</b><br>${c.consistency?`Best day ${money(a.best_day_profit??Math.max(0,...Object.values(a.daily||{})))} ÷ ${esc(c.denominator)} profit ${money(a.consistency_denominator??a.profit)}<br>Current ${a.consistency_pct==null?'— (no positive denominator)':a.consistency_pct.toFixed(2)+'%'} · ${a.consistency_met?'Rule met':'More distributed profit needed'}<br>Additional profit needed for consistency: ${money(a.consistency_remaining??0)}<br>Exceeding the ratio delays eligibility; it does not fail the account.`:'This phase has no best-day share requirement.'}</p>${holidaySchedule(state.challenge_schedule)}<details><summary>Exact rules & verification</summary><p>${esc(a.version)} · ${esc(ref?.version||'custom')} · ${esc(c.phase)}<br>${esc(c.mode)} drawdown ${money(c.drawdown)} · ${c.phase==='funded'?'no pass target':'target '+money(c.target)}<br>Daily loss ${money(c.daily_loss)} (${esc(c.daily_action)})<br>Consistency ${c.consistency?`≤ ${c.consistency}% of ${esc(c.denominator)}`:'not required'} · current ${a.consistency_pct===null?'—':a.consistency_pct.toFixed(2)+'%'}<br>Minimum ${c.min_days||0} trading days · cap ${c.max_micro} micros / ${c.micro_only?0:Math.floor(c.max_micro/c.micro_per_mini)} minis<br>Entry cutoff ${esc(c.entry_cutoff||'custom: none')} · flatten ${esc(c.flatten_time||'none')} Chicago<br>EOD ${esc(c.eod_time||'17:00 rollover')} · reset 17:00 Chicago</p>${warnings.length?`<ul>${warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p>${(ref?.sources||[]).map((u,i)=>`<a href="${esc(u)}" target="_blank" rel="noopener">Source ${i+1}</a>`).join(' · ')}</p><p>Local simulation only. Modeled criteria are not firm certification.</p></details>`}

for(let [id,delta] of [['qtyUp',1],['qtyDown',-1]])$(id).onclick=()=>{if(!draft||busy)return;$('quantity').value=Math.max(1,(+$('quantity').value)+delta);readDraft();persistDraft()};
for(let [id,delta] of [['scaleUp',1],['scaleDown',-1]])$(id).onclick=()=>{command('scale',{delta})};

let propCatalog=[];
function filterPresets(){const previous=$('challengePreset').value;$('challengePreset').replaceChildren(new Option('Custom rules · any firm',''));for(const p of propCatalog.filter(p=>(!$('firmFilter').value||p.firm===$('firmFilter').value)&&(!$('phaseFilter').value||p.phase===$('phaseFilter').value))){$('challengePreset').add(new Option(`${p.firm} · ${p.plan} · $${p.balance.toLocaleString()} · ${p.phase}`,p.id))}if([...$('challengePreset').options].some(o=>o.value===previous))$('challengePreset').value=previous;else{$('challengeEnabled').checked=false;$('presetDetails').textContent='Choose a plan to load its rules, or enable custom rules.'}}
$('firmFilter').onchange=filterPresets;$('phaseFilter').onchange=filterPresets;
fetch('/prop_catalog.json').then(r=>r.json()).then(x=>{propCatalog=x.presets;for(const firm of [...new Set(propCatalog.map(p=>p.firm))])$('firmFilter').add(new Option(firm,firm));filterPresets()}).catch(()=>{$('presetDetails').textContent='Rule catalog unavailable; custom settings remain available.'});
$('challengePreset').onchange=()=>{let p=propCatalog.find(p=>p.id===$('challengePreset').value);if(!p){$('presetDetails').textContent='Custom rules. No official firm compliance claim.';return}$('challengeEnabled').checked=true;$('balance').value=p.balance;for(let [id,k] of Object.entries({challengeTarget:'target',challengeDrawdown:'drawdown',challengeMode:'mode',challengeLock:'lock_profit',challengeDaily:'daily_loss',challengeBasis:'daily_basis',challengeConsistency:'consistency',challengeDenominator:'denominator',challengeCap:'max_micro',challengeRatio:'micro_per_mini',challengePhase:'phase',challengeAction:'daily_action',challengeDays:'min_days'}))$(id).value=p.config[k];$('presetDetails').innerHTML=`<p><b>${p.phase==='funded'?'Funded risk practice · no evaluation pass target':'Modeled pass criteria: reach '+money(p.config.target)}</b>, keep equity above the loss floor (${money(p.config.drawdown)} ${esc(p.config.mode)} drawdown), <strong>Consistency: ${p.config.consistency?'best day ≤ '+p.config.consistency+'% of '+esc(p.config.denominator)+' profit':'not required in this phase'}</strong>; ${p.config.min_days||0} minimum trading days. ${p.config.pass_at_eod?'Checked at modeled end of day.':'Checked after completed execution, with positions closed.'}</p><p>${esc(p.phase_note||'Evaluation snapshot; funded payout rules are separate.')}</p><details><summary>Sources, schedule & limitations</summary><p>${esc(p.support)} · ${esc(p.version)} · checked ${p.retrieved}. Personal risk/loss controls remain unchanged.</p><p>Chicago: entry cutoff ${esc(p.config.entry_cutoff||'none')}, flatten ${esc(p.config.flatten_time||'none')}, EOD ${esc(p.config.eod_time||'17:00')}; reset 17:00</p>${holidayPreset(p.config)}<ul>${p.limitations.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><p>${p.sources.map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener">Official source ${i+1}</a>`).join(' · ')}</p></details>`};

async function previewDate(){let g=++dateGeneration;$('datePreview').textContent='Checking exact time and synchronized coverage…';try{let r=await api('resolve-date?local='+encodeURIComponent($('startDate').value)+'&dataset='+encodeURIComponent($('dataset').value)+'&resolution='+$('executionResolution').value);if(g!==dateGeneration)return;$('datePreview').textContent=`${r.local.replace('T',' ')} Chicago · ${r.minutes}m · ${r.flow?'matched flow window':'no matched flow'} · ${r.label}. ${r.regular_session_complete?'Full regular session recorded.':'Regular session has gaps or is shortened.'} ${r.note}`;$('sessionError').textContent='';}catch(e){if(g!==dateGeneration)return;$('datePreview').textContent=e.message;}}
$('randomSession').onclick=async()=>{let g=++dateGeneration;$('randomSession').disabled=true;try{let r=await api('random-date?'+new URLSearchParams({start:$('randomStart').value,end:$('randomEnd').value,resolution:$('randomResolution').value,flow:String($('randomFlow').checked)}));if(g!==dateGeneration)return;$('dataset').value=r.dataset;$('executionResolution').value=String(r.minutes);$('startDate').value=r.local;dateSelection=r.selection;await previewDate();notify(`Random session: ${r.local.slice(0,10)} from ${r.selection.eligible_dates} eligible dates`)}catch(e){if(g===dateGeneration)$('datePreview').textContent=e.message+' Selected replay date is unchanged.'}finally{$('randomSession').disabled=false}};

$('closeRisk').onclick=()=>$('riskDialog').close();
$('saveRisk').onclick=async()=>{if(busy)return;$('saveRisk').disabled=true;try{const ok=await command('risk-settings',{enforced:$('riskEnforced').checked,risk:+$('riskAmount').value,loss:+$('lossAmount').value,max_micro:+$('riskContracts').value});if(ok)$('riskDialog').close();else $('riskError').textContent='Could not save. Check the limits and cancel any queued order first.'}finally{$('saveRisk').disabled=false}};


// Compact terminal shell. Order shortcuts open the existing validated bracket draft.
function showTerminal(){document.querySelectorAll('dialog[open]').forEach(d=>d.close())}
$('navTerminal').onclick=showTerminal;
$('navSessions').onclick=()=>sessionDialog();
$('navRisk').onclick=()=>{if(!state)sessionDialog();else $('settingsButton').click()};
$('navHelp').onclick=()=>$('helpButton').click();
let quickQueued=0;
for(const [id,side] of [['quickBuy',1],['quickSell',-1]])$(id).onclick=async()=>{
 if(!state){sessionDialog();return}
 const qty=Number($('quickQuantity').value),instrument=$('contract').value;
 if(!Number.isInteger(qty)||qty<1){notify('Use a positive whole-contract quantity.');return}
 const brackets=$('quickBrackets').checked;if(needsEntryStop(state.session,side,qty,brackets)){renderQuickRisk();return}const sl=+$('quickStop').value,tp=+$('quickTarget').value;
 if(brackets&&![sl,tp].every(n=>Number.isFinite(n)&&n>0&&Math.abs(n*4-Math.round(n*4))<1e-7)){notify('Use positive quarter-point bracket distances.');return}
 // Distances and click order are captured now; the server uses its latest causal quote.
 quickQueued++;$('quickStatus').textContent=`${quickQueued} request(s) queued`;
 const ok=await command('quick-order',{instrument,side,qty,brackets,stop_points:sl,target_points:tp});
 quickQueued--; $('quickStatus').textContent=quickQueued?`${quickQueued} request(s) queued`:ok?'Accepted · next source open':'Rejected · see message';
};
$('quickBrackets').onchange=()=>{for(const id of ['quickStop','quickTarget']){$(id).disabled=!$('quickBrackets').checked;$(id).parentElement.hidden=!$('quickBrackets').checked;} render();};
$('quickFlatten').onclick=()=>{if(state?.session.position)return command('manage',{flatten:true});if(state?.session.pending)return command('cancel');};
$('closeJournal').onclick=()=>$('journalDialog').close();
$('navJournal').onclick=()=>{
 if(!state){notify('Wait for the saved attempt to load, or start a replay.');return}pause();const trades=state?.session.trades||[],wins=trades.filter(t=>t.net>0),losses=trades.filter(t=>t.net<0),profit=wins.reduce((n,t)=>n+t.net,0),loss=-losses.reduce((n,t)=>n+t.net,0),net=profit-loss;
 const cards=[['Trades',trades.length,'Completed in this attempt'],['Win rate',trades.length?(wins.length/trades.length*100).toFixed(1)+'%':'—',wins.length+' wins · '+losses.length+' losses'],['Profit factor',loss?(profit/loss).toFixed(2):'—',loss?'Net winning / losing trades':'No losing trades to calculate ratio'],['Net P&L',money(net),'Expectancy / trade '+(trades.length?money(net/trades.length):'—')]];
 $('journalMetrics').innerHTML=cards.map(([name,value,note])=>`<article><span>${esc(name)}</span><strong class="${name==='Net P&L'&&net<0?'negative':''}">${esc(value)}</strong><p>${esc(note)}</p></article>`).join('');
 $('journalTrades').innerHTML=trades.length?'<table><thead><tr><th>Contract</th><th>Side</th><th>Qty</th><th>Entry</th><th>Exit</th><th>Net P&L</th><th>Exit time · Chicago</th><th>Exit reason / review</th></tr></thead><tbody>'+trades.slice().reverse().map(t=>`<tr><td>${esc(t.instrument)}</td><td>${t.side===1?'Long':'Short'}</td><td>${t.qty}</td><td>${price(t.entry)}</td><td>${price(t.exit)}</td><td class="${t.net>=0?'positive':'negative'}">${money(t.net)}</td><td>${time(t.exit_available)}</td><td>${esc(t.reason||'—')}<label>Why I took this trade<textarea data-trade-note="${esc(t.id)}" rows="2" maxlength="10000">${esc(t.trader_notes||'')}</textarea></label><button data-save-trade="${esc(t.id)}">Save trade review</button><span data-trade-status="${esc(t.id)}" role="status"></span></td></tr>`).join('')+'</tbody></table>':'<p class="quiet">No completed trades in this replay attempt.</p>';
 $('journalNotes').value=state?.session.notes||'';$('saveJournalNotes').disabled=!state;$('journalSaveStatus').textContent='Saved only on this computer.';$('journalDialog').showModal();
};


$('quickQuantity').onchange=()=>{if(draft&&!busy&&$('quickQuantity').checkValidity()){$('quantity').value=$('quickQuantity').value;readDraft();persistDraft()}};

// Visible navigation labels and consistent return-to-chart behavior.
for(const id of ['navTerminal','navJournal','navRisk','navSessions','navHelp']){
 const button=$(id),previous=button.onclick;
 button.onclick=()=>{showTerminal();document.querySelectorAll('.terminal-rail button').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-current',b===button?'page':'false')});previous?.();};
}
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('close',()=>{document.querySelectorAll('.terminal-rail button').forEach(b=>{const active=b.id==='navTerminal';b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false')});});

$('accountRisk').onclick=()=>$('navRisk').click();
$('replaySession').onclick=sessionDialog;

$('saveJournalNotes').onclick=async()=>{const text=$('journalNotes').value;$('saveJournalNotes').disabled=true;const ok=await command('note',{notes:text});$('journalSaveStatus').textContent=ok?'Review saved.':'Not saved. Check the error and retry.';$('saveJournalNotes').disabled=false;};

$('journalNotes').oninput=()=>{$('journalSaveStatus').textContent='Unsaved changes — choose Save review.';};

$('rewind').onclick=async()=>{pause();selected=null;previewStop=null;if(await command('rewind')){charts.forEach(c=>c.current());notify('Rewound one source candle. Later results were archived locally. This attempt has seen future prices.');}};

function renderQuickRisk(){
 const s=state?.session,q=+$('quickQuantity').value,brackets=$('quickBrackets').checked;
 const forbidden=!!s&&quantityLimit(s,$('contract').value)===0;
 const buy=forbidden||needsEntryStop(s,1,q,brackets),sell=forbidden||needsEntryStop(s,-1,q,brackets);
 if(forbidden){$('long').disabled=true;$('short').disabled=true;}
 $('quickBuy').disabled||=buy;$('quickSell').disabled||=sell;
 $('quickRiskConflict').hidden=!!s?.ended||!(buy||sell);
 $('quickRiskExplanation').textContent=forbidden?'This plan allows micro contracts only. Choose MNQ or MES.':s?.challenge?'This challenge requires a stop for new entries. Enable TP/SL.':'TP/SL is off. Enforced risk limits require a stop for new entries. Enable TP/SL or choose warning-only practice.';
 $('quickWarningMode').hidden=!!s?.challenge;
 $('quickWarningMode').disabled=busy;
}
$('quickWarningMode').onclick=async()=>{if(!state||busy)return;const s=state.session;if(s.challenge)return;if(await command('risk-settings',{enforced:false,risk:s.risk,loss:s.initial-s.floor,max_micro:s.max_micro??10})){$('notice').textContent='';$('quickStatus').textContent='Warning-only practice · orders may have no stop.';}};
$('quickQuantity').addEventListener('input',()=>{if(state)render()});

function updateStartMode(){
 const random=$('randomStartMode').checked;
 for(const id of ['startDate','latestSession','dataset'])$(id).disabled=random;
 $('create').textContent=random?'Start randomized practice':'Create manual replay';
 $('datePreview').hidden=random;
}
$('randomStartMode').onchange=updateStartMode;

$('nextDay').onclick=async()=>{pause();if(await command('next-day'))charts.forEach(c=>c.current());};

$('journalTrades').onclick=async e=>{const button=e.target.closest('[data-save-trade]');if(!button)return;const id=button.dataset.saveTrade;const area=$('journalTrades').querySelector(`textarea[data-trade-note="${id}"]`);button.disabled=true;const ok=await command('trade-note',{trade_id:id,notes:area.value});button.disabled=false;$('journalTrades').querySelector(`[data-trade-status="${id}"]`).textContent=ok?'Saved':'Save failed — retry';};
